import java.util.ArrayList;
import java.util.Arrays;
import java.util.Scanner;
import java.util.StringTokenizer;

public class TextDoc {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int numberOfLines = scanner.nextInt();
        scanner.nextLine();
        String inputLine = scanner.nextLine();
        String[] parts = inputLine.split("\\(.*?\\)");
        int maxLength = 0;
        for (String part : parts) {
            StringTokenizer tokenizer = new StringTokenizer(part, "_");
            while (tokenizer.hasMoreTokens()) {
                String token = tokenizer.nextToken();
                maxLength = Math.max(token.length(), maxLength);
            }
        }
        ArrayList<String> bracketsContent = new ArrayList<>();
        char openBracket = '(';
        char closeBracket = ')';
        int lastOpenIndex = -1;
        for (int i = 0; i < inputLine.length(); i++) {
            char currentChar = inputLine.charAt(i);
            if (currentChar == openBracket) {
                lastOpenIndex = i;
            }
            if (currentChar == closeBracket && lastOpenIndex != -1) {
                bracketsContent.add(inputLine.substring(lastOpenIndex + 1, i));
            }
        }
        int totalWords = 0;
        for (String segment : bracketsContent) {
            String[] words = segment.split("_");
            for (String word : words) {
                if (word.length() > 0) {
                    totalWords++;
                }
            }
        }
        System.out.println(maxLength + " " + totalWords);
    }
}
